 * quotes so paths with spaces (Windows) survive. Exported for tests. */
export function splitCommand(raw: string): string[] {
  const parts: string[] = [];
  const re = /"([^"]*)"|'([^']*)'|(\S+)/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(raw)) !== null) parts.push(m[1] ?? m[2] ?? m[3]);
  return parts;
}

